```ts
zfd.formData({
  name: zfd.text()
})._input
```
is now of type `FormData` instead of `{ name: string }`.

```ts
const formDataSchema = zfd.formData({
  name: zfd.text()
})

const form = formDataSchema.parse(formData)
```
`form` is still typed as `{ name: string }` here.

I need this type to be correct so input types are inferred accurately for a form data integration I'm working on for [tRPC](https://github.com/trpc/trpc/compare/trpc:09634d5...trpc:bea7865#diff-ac3ed79d27fe031890ac3a59f5d04d89d6848ce5dae67f6594d9aff23721e279R95).

HasSBOM:

- Description: attestation that the package/artifact/source has an SBOM associated with it 

- Subject:      pkg / src
- Object:        
- Properties: uri ( string )
                      source ( string )
                      collector ( string )

```
fragment allHasSBOMTree on HasSBOM {
  uri
  subject {
    __typename 
    ... on Package {
      type
      namespaces {
        namespace
        names {
          name
          versions {
            version
            qualifiers {
              key
              value
            }
            subpath
          }
        }
      }
    }
   ...on Source {
      type
      namespaces {
        namespace
        names {
          name
          tag
          commit
        }
      }
    }
  }
  origin
  collector
}

query Q1 {
  HasSBOMs(hasSBOMSpec: {}) {
    ...allHasSBOMTree
  }
}

query Q2 {
  HasSBOMs(hasSBOMSpec: {origin: "testing backend"}) {
    ...allHasSBOMTree
  }
}

query Q3 {
  HasSBOMs(hasSBOMSpec: {package: {name: "openssl"}}) {
    ...allHasSBOMTree
  }
}

query Q4 {
  HasSBOMs(hasSBOMSpec: {source: {name: "github.com/guacsec/guac"}}) {
    ...allHasSBOMTree
  }
}

query Q5 {
  HasSBOMs(hasSBOMSpec: {package: {name: "openssl"}, source: {name: "github.com/guacsec/guac"}}) {
    ...allHasSBOMTree
  }
}
```

